void need(bool b,const std::string&s){if(!b)throw std::runtime_error(s);}
Z absz(Z a){return a<0?-a:a;} Z gcdz(Z a,Z b){a=absz(a);b=absz(b);while(b!=0){Z r=a%b;a=b;b=r;}return a;}
Z ten(int n){Z v=1;while(n--)v*=10;return v;}
struct Q{Z n,d;Q(long long x=0):n(x),d(1){}Q(Z x,Z y):n(x),d(y){norm();}explicit Q(const std::string&s){auto p=s.find('/');n=Z(s.substr(0,p));d=p==s.npos?Z(1):Z(s.substr(p+1));norm();}void norm(){need(d!=0,"zero denominator");if(d<0){n=-n;d=-d;}Z g=gcdz(n,d);n/=g;d/=g;}std::string str()const{return n.convert_to<std::string>()+(d==1?"":"/"+d.convert_to<std::string>());}};
Q operator-(const Q&a){return Q(-a.n,a.d);}Q operator+(const Q&a,const Q&b){Z g=gcdz(a.d,b.d);return Q(a.n*(b.d/g)+b.n*(a.d/g),(a.d/g)*b.d);}Q operator-(const Q&a,const Q&b){return a+(-b);}Q operator*(const Q&a,const Q&b){Z g=gcdz(a.n,b.d),h=gcdz(b.n,a.d);return Q((a.n/g)*(b.n/h),(a.d/h)*(b.d/g));}Q operator/(const Q&a,const Q&b){need(b.n!=0,"zero divisor");return a*Q(b.d,b.n);}bool operator<(const Q&a,const Q&b){return a.n*b.d<b.n*a.d;}bool operator>(const Q&a,const Q&b){return b<a;}bool operator>=(const Q&a,const Q&b){return !(a<b);}bool operator<=(const Q&a,const Q&b){return !(b<a);}bool operator==(const Q&a,const Q&b){return a.n==b.n&&a.d==b.d;}bool operator!=(const Q&a,const Q&b){return !(a==b);}Q mn(Q a,Q b){return a<b?a:b;}Q mx(Q a,Q b){return a>b?a:b;}Q powq(Q a,int n){Q r(1);while(n){if(n&1)r=r*a;a=a*a;n>>=1;}return r;}
Z floorz(const Q&a){Z q=a.n/a.d;if(a.n<0&&a.n%a.d!=0)--q;return q;}Z ceilz(const Q&a){return -floorz(-a);}Q lower(const Q&a){Z g=ten(45);return Q(floorz(a*Q(g,1)),g);}Q upper(const Q&a){Z g=ten(45);return Q(ceilz(a*Q(g,1)),g);}
Q jq(const J&j){return j.is_string()?Q(j.get<std::string>()):Q(j.dump());}J read(const std::string&s){std::ifstream f(s);need(bool(f),"cannot open "+s);J j;f>>j;return j;}
struct IV{Q lo,hi;};std::map<std::string,IV>logcache;
IV shortlog(Q x){Q z=(x-Q(1))/(x+Q(1)),zz=z*z,p=z,s;for(int j=0;j<80;j++){s=s+p/Q(2*j+1);p=p*zz;}Q lo=Q(2)*s,tail=Q(2)*p/(Q(161)*(Q(1)-zz));return {lo,lo+tail};}
Q independentDown(const Q&a){Z grid=ten(60);return Q(floorz(a*Q(grid,1)),grid);}Q independentUp(const Q&a){Z grid=ten(60);return Q(ceilz(a*Q(grid,1)),grid);}
IV logiv(Q x){need(x>=Q(1),"independent base2 logarithm domain");auto key=x.str();if(logcache.count(key))return logcache[key];int k=0;while(x>Q(2)){x=x/Q(2);k++;}IV one=shortlog(x),two=shortlog(Q(2));return logcache[key]={independentDown(Q(k)*two.lo+one.lo),independentUp(Q(k)*two.hi+one.hi)};}
IV expiv(Q lo,Q hi){need(Q(0)<=lo&&lo<=hi&&hi<Q(1,4),"independent degree16 exponential domain");auto polynomial=[](Q x){Q sum(1),term(1);for(int j=1;j<=16;j++){term=term*x/Q(j);sum=sum+term;}return sum;};Z fact=1;for(int j=1;j<=17;j++)fact*=j;Q tail=powq(hi,17)/Q(fact,1)/(Q(1)-hi/Q(18));return {independentDown(polynomial(lo)),independentUp(polynomial(hi)+tail)};}struct Row{long long t,n;IV log;};struct P{long long m,W,N,L,rank,maxchild,count=0;std::vector<Row>rows;};
P prepare(J j){if(j.contains("profile"))j=j["profile"];if(j.contains("scaled_moment_profile"))j=j["scaled_moment_profile"];P p;need(j.at("m").is_number_integer(),"integer m");p.m=j.at("m");p.W=j.contains("W")?j.at("W").get<long long>():j.at("W_per_vertex").get<long long>();p.N=j.contains("N")?j.at("N").get<long long>():j.at("deficit_per_vertex").get<long long>();p.L=j.value("L",0LL);p.rank=j.contains("total_rank")?j.at("total_rank").get<long long>():j.at("rank_per_vertex").get<long long>();p.maxchild=j.at("maxchild");auto h=j.contains("child_multiplicities")?j["child_multiplicities"]:j["child_histogram"];std::map<long long,long long>hist;for(auto it=h.begin();it!=h.end();++it){need(it.value().is_number_integer(),"integer multiplicity");long long t=std::stoll(it.key()),n=std::stoll(it.value().dump());need(std::to_string(t)==it.key(),"aliased histogram key");need(t>0&&t<p.m&&n>0,"invalid histogram");hist[t]=n;}need(!hist.empty(),"empty histogram");Z mass=0;for(auto [t,n]:hist){mass+=Z(t)*n;p.count+=n;p.rows.push_back({t,n,logiv(Q(p.m,t))});}need(p.m>1&&p.W>0&&mass==p.rank&&mass==Z(p.W)*p.m-p.N+p.L,"rank mass");need(hist.rbegin()->first==p.maxchild&&mass>0&&mass<Z(p.W)*p.m,"max child/contraction");return p;}
J profilej(const P&p){J h;for(auto&r:p.rows)h[std::to_string(r.t)]=r.n;return J{{"m",p.m},{"W",p.W},{"N",p.N},{"L",p.L},{"total_rank",p.rank},{"maxchild",p.maxchild},{"child_multiplicities",h}};}
struct M{Q lo,hi,rawlo,rawhi,flo,fhi;J terms;};
M moment(const P&p,Q a,bool paid,bool detail=false){need(a>=Q(0),"negative saving");M o;for(auto&r:p.rows){IV e=expiv(a*r.log.lo,a*r.log.hi);Q w(Z(r.t)*r.n,Z(p.m)*p.W);o.rawlo=o.rawlo+w*e.lo;o.rawhi=o.rawhi+w*e.hi;if(detail)o.terms.push_back(J{{"child",r.t},{"multiplicity",r.n},{"log_lower",r.log.lo.str()},{"log_upper",r.log.hi.str()},{"exp_lower",e.lo.str()},{"exp_upper",e.hi.str()},{"contribution_lower",(w*e.lo).str()},{"contribution_upper",(w*e.hi).str()}});}if(paid){IV l=logiv(Q(p.m)),e=expiv(a*l.lo,a*l.hi);Q weight(Z(32)*p.m*p.count,Z(p.W)*ten(16));o.flo=weight*e.lo;o.fhi=weight*e.hi;}o.lo=o.rawlo+o.flo;o.hi=o.rawhi+o.fhi;return o;}
J mj(const P&p,Q a,const M&o,bool paid){J j={{"saving",a.str()},{"lower",o.lo.str()},{"upper",o.hi.str()},{"strict_gap_lower",(Q(1)-o.hi).str()}};if(paid){j["raw"]=J{{"saving",a.str()},{"lower",o.rawlo.str()},{"upper",o.rawhi.str()},{"strict_gap_lower",(Q(1)-o.rawhi).str()}};if(!o.terms.is_null())j["raw"]["terms"]=o.terms;j["fallback_lower"]=o.flo.str();j["fallback_upper"]=o.fhi.str();j["bad_fraction"]=Q(1,ten(16)).str();j["edge_count"]=p.count;j["fallback_children_per_edge"]=32*p.m*p.m;}else if(!o.terms.is_null())j["terms"]=o.terms;return j;}
struct Saved{Q a,atom,ordinary;J j;};
Saved certify(const P&p,bool paid){Z den=ten(18),lo=0,hi=den/(paid?100:32);need(moment(p,Q(lo,den),paid).hi<Q(1),"zero saving");need(moment(p,Q(hi,den),paid).lo>Q(1),"upper bracket");int it=0;while(hi-lo>1){Z mid=(hi+lo)/2;M r=moment(p,Q(mid,den),paid);if(r.hi<Q(1))lo=mid;else if(r.lo>Q(1))hi=mid;else throw std::runtime_error("interval overlaps one");++it;}need(moment(p,Q(lo,den),paid).hi<Q(1)&&moment(p,Q(hi,den),paid).lo>Q(1),"adjacent saving enclosure");Saved s;s.a=Q(lo,den);s.j={{"saving",s.a.str()},{"accepted",mj(p,s.a,moment(p,s.a,paid,true),paid)},{"rejected",mj(p,Q(hi,den),moment(p,Q(hi,den),paid,true),paid)},{"denominator",den.convert_to<std::string>()},{"iterations",it}};if(paid){Q old(384599,ten(10)),thr=s.a/(Q(1)+s.a-old);Z ag=ten(24);s.atom=Q(floorz(thr*Q(ag,1))+1,ag);s.ordinary=(Q(1)-s.atom)*s.a+s.atom*old;need(s.ordinary<s.atom&&s.atom<Q(1)-s.ordinary,"atom toll");need(Q(Z(2)*p.m*p.m*p.m,Z(1)<<80)<Q(1,ten(16)),"rare class");need(Q(p.rank)+Q(Z(32)*p.m*p.m*p.count,ten(16))<Q(Z(p.W)*p.m,1),"contaminated mass");Q prev=s.atom-Q(1,ag);need(prev<=(Q(1)-prev)*s.a+prev*old,"previous atom control");s.j["coarse_saving"]=s.a.str();s.j["ordinary_saving"]=s.ordinary.str();s.j["atom_beta"]=s.atom.str();s.j["atom_threshold"]=thr.str();s.j["atom_lower_gap"]=(s.atom-s.ordinary).str();s.j["atom_upper_gap"]=(Q(1)-s.atom-s.ordinary).str();}return s;}
J assembly(Q a,Q b,Q k,Q eta,Q beta,Q literal,Q rowgap){Q tau=Q(1)-a,sigma=Q(1)-b,q=a*(Q(1)-Q(2)*eta),lp=Q(1)-q,lam=(tau+lp)/Q(2),c=q+eta/Q(4),eps=(Q(1)-eta)/(Q(1)+q),minimum=eps*q,r=(minimum+Q(1)-eps)/Q(2),delta=eta/Q(8),internal=tau+(Q(1)-beta)*mx(sigma-tau,Q(0)),leaf=sigma+beta*(Q(1)-sigma);std::map<std::string,Q>m={{"balanced_prefix",Q(1)-eps},{"coordinate_movement",a},{"compact_phase_layer",minimum},{"bulk_exposure",a},{"Gaussian_arithmetic",mn(Q(1)-eps-delta,r-delta)},{"scalar_work",Q(1)-eps-delta},{"dimension",eps}};
std::map<std::string,Q>s={{"bit_positive",a},{"complex_above_bit",b-a},{"complex_below_one_over32",Q(1,32)-b},{"beta_positive",beta},{"beta_below_one",Q(1)-beta},{"leaf_saving_above_bit",(Q(1)-beta)*b-a},{"q_positive",q},{"q_below_internal",Q(1)-internal-q},{"q_below_leaf",Q(1)-leaf-q},{"c_positive",c},{"c_below_one",Q(1)-c},{"q_below_reservations",c-q},{"lambda_above_tau",lam-tau},{"lambda_above_sigma",lam-sigma},{"lambda_above_internal",lam-internal},{"lambda_prime_above_lambda",lp-lam},{"compact_leaf",lp-leaf},{"compact_reservations",lp-(Q(1)-c)},{"lambda_prime_below_one",q},{"epsilon_positive",eps},{"epsilon_below_one",Q(1)-eps},{"guard_width",Q(1)-eps},{"K_geometry",Q(1)-eps*(Q(1)+c)},{"K_dominates_log",eps*c},{"record_suffix",Q(1)-eps},{"phase_local",Q(1)-eps-delta},{"phase_boundary",r-delta},{"gamma_sublinear",Q(1)-eps-r},{"cell_above_band",eps-(Q(1)-r)/Q(2)},{"prime_interval_packing",Q(1)-eps},{"alpha_positive",r},{"alpha_below_one",Q(1)-r},{"alpha_below_one_fourth",Q(1,4)-r},{"delta_positive",delta},{"delta_below_one_eighth",Q(1,8)-delta},{"short_record_fallback",eps-a},{"small_field_exposure",Q(1)-eps-minimum},{"artificial_boundary",Q(8)-eps+r-delta-minimum},{"literal_scalar_guard",literal},{"row_product_gap",rowgap}};
Q mm(100);J margins,slacks;for(auto [name,v]:m){mm=mn(mm,v);margins[name]=v.str();s[name+"_above_kappa"]=v-k;}need(mm==minimum&&Q(1)-eps-minimum==eta&&Q(1)-eps-r==eta/Q(2)&&Q(1)-eps*(Q(1)+c)==eta-eps*eta/Q(4),"assembly identities");need(s.size()==47,"47 constraints");for(auto [name,v]:s){need(v>Q(0),"nonpositive constraint "+name);slacks[name]=v.str();}return J{{"parameters",{{"a_bit",a.str()},{"a_complex",b.str()},{"beta",beta.str()},{"eta",eta.str()},{"kappa",k.str()},{"tau",tau.str()},{"sigma",sigma.str()},{"q",q.str()},{"lambda_",lam.str()},{"lambda_prime",lp.str()},{"c",c.str()},{"epsilon",eps.str()},{"alpha_squared_power",r.str()},{"delta",delta.str()}}},{"recurrence",{{"internal",internal.str()},{"leaf",leaf.str()},{"reservations",(Q(1)-c).str()}}},{"margins",margins},{"minimum_margin",minimum.str()},{"absorption_gap",(minimum-k).str()},{"strict_constraints",slacks}};}
J malformedControls(J valid){J names=J::array();auto test=[&](J bad,const std::string&name){bool rejected=false;try{prepare(bad);}catch(const std::exception&){rejected=true;}need(rejected,"malformed control accepted "+name);names.push_back(name);};J b=valid;b["total_rank"]=b["total_rank"].get<long long>()+1;test(b,"incorrect total rank");b=valid;b["child_multiplicities"]["01"]=1;test(b,"aliased histogram key");b=valid;b["child_multiplicities"]["1"]=0;test(b,"zero multiplicity");b=valid;b["child_multiplicities"][std::to_string(b["m"].get<long long>())]=1;test(b,"uncontracted child");b=valid;b["child_multiplicities"]["1"]=1.5;test(b,"fractional multiplicity");b=valid;b["child_multiplicities"]=J::object();test(b,"empty histogram");return names;}
