void compareMoment(const J&got,const J&want,const std::string&path){for(std::string k:{"saving","lower","upper","strict_gap_lower","fallback_lower","fallback_upper"})if(want.contains(k))compareQ(got.at(k),want.at(k),path+"."+k);if(want.contains("raw"))compareMoment(got.at("raw"),want.at("raw"),path+".raw");if(want.contains("terms")){need(got.at("terms").size()==want.at("terms").size(),"terms count");for(size_t i=0;i<want.at("terms").size();i++)for(auto it=want.at("terms")[i].begin();it!=want.at("terms")[i].end();++it)compareQ(got.at("terms")[i].at(it.key()),it.value(),path+".term"+std::to_string(i)+"."+it.key());}}
int main(int argc,char**argv){try{need(argc==4||argc==5,"independent-pricing FROZEN OUTPUT BANK_RECEIPT [PROFILE_NORMALIZATION]");J saved=read(argv[1]);P bp=prepare(saved["bit_profile"]),cp=prepare(saved["complex_profile"]);Q c=jq(saved["bit"]["saving"]),b=jq(saved["a_complex"]);M bit=moment(bp,c,true,true),bitNext=moment(bp,c+Q(1,ten(18)),true,true),complex=moment(cp,b,false,true),complexNext=moment(cp,b+Q(1,ten(18)),false,true);need(bit.hi<Q(1)&&bitNext.lo>Q(1),"independent bit paid adjacent saving");need(complex.hi<Q(1)&&complexNext.lo>Q(1),"independent complex adjacent saving");Q old(384599,ten(10)),threshold=c/(Q(1)+c-old),atom(floorz(threshold*Q(ten(24),1))+1,ten(24));Q a=(Q(1)-atom)*c+atom*old;need(a<atom&&atom<Q(1)-a,"independent atom row toll");need(Q(Z(2)*bp.m*bp.m*bp.m,Z(1)<<80)<Q(1,ten(16)),"independent rare-class probability");need(Q(bp.rank)+Q(Z(32)*bp.m*bp.m*bp.count,ten(16))<Q(Z(bp.W)*bp.m,1),"independent full bad-class rank mass");J chain=J::array();chain.push_back(a.str());need(a==jq(saved["ordinary_chain"][0]),"initial paid ordinary exact equality");for(int j=1;j<(int)saved["ordinary_chain"].size();j++){Q next=(Q(1)-c)*c+c*a;need(a<next&&next<c&&c<Q(1)-next,"finite bootstrap acyclic toll");a=next;need(a==jq(saved["ordinary_chain"][j]),"independent bootstrap level equality");chain.push_back(a.str());}Q eta=jq(saved["assembly"]["parameters"]["eta"]),beta=jq(saved["assembly"]["parameters"]["beta"]);a=mn(a,(Q(1)-beta)*b-Q(1,ten(30)));need(a==jq(saved["a_bit"]),"final bit exponent equality");Q k=jq(saved["kappa"]);Q literal=jq(saved["finite_bridge_guards"]["literal_scalar_guard"]),rowgap=jq(saved["finite_bridge_guards"]["row_product_gap"]);J exact=assembly(a,b,k,eta,beta,literal,rowgap);for(auto&[name,gap]:saved["assembly"]["strict_constraints"].items())need(jq(gap)==jq(exact["strict_constraints"][name]),"independent exact inequality margin mismatch "+name);need(exact["strict_constraints"].size()==47,"all47 inequalities");bool rejected=false;try{assembly(a,b,k+Q(1,ten(18)),eta,beta,literal,rowgap);}catch(std::exception&e){rejected=true;}need(rejected,"independent adjacent kappa rejection");J banks=read(argv[3]);int replicas=banks.at("physical_replicas").get<int>(),normalizer=banks.at("arithmetic_normalization").get<int>();need(replicas==3*normalizer && (replicas==9||replicas==72),"literal three-stage bank normalization");J normalization={{"physical_replicas",replicas},{"per_local_three_stage_histogram_multiplier",normalizer},{"per_local_operation_graph_multiplier",replicas}};if(replicas==72)need(argc==5,"72-replica pricing requires explicit corrected profile normalization receipt");if(argc==5){J anchor=read(argv[4]);need(anchor.at("frame_histogram_scale").get<int>()==replicas,"wrong explicit operation-graph histogram scale");normalization["source_receipt"]=argv[4];normalization["explicit_frame_histogram_scale"]=anchor["frame_histogram_scale"];}Q router=jq(banks.contains("selector_calls")?banks["selector_calls"]:banks["conservative_extra_selector_calls"]);need(router>Q(0)&&router<Q((Z(1)<<40),1),"fully charged native chart routing coefficient");need(c<Q(1)-a,"strict positive fixed ordinary routing absorption gap");J out={{"status","PASS_INDEPENDENT_BASE2_DEGREE16_MOMENT_AND_ASSEMBLY"},{"kappa",k.str()},{"paid_bit_accepted",mj(bp,c,bit,true)},{"paid_bit_next_rejected",mj(bp,c+Q(1,ten(18)),bitNext,true)},{"complex_accepted",mj(cp,b,complex,false)},{"complex_next_rejected",mj(cp,b+Q(1,ten(18)),complexNext,false)},{"ordinary_chain",chain},{"assembly",exact},{"constraints_matched",47},{"adjacent_kappa_rejected",true},{"native_chart_selector_calls",router.str()},{"physical_profile_normalization",normalization},{"fixed_routing_absorption_gap",(Q(1)-a-c).str()},{"backend","independently range-reduced base2 atanhs80 and exponential degree16, outward decimalgrid60; generic rational and assembly identities retained"},{"scope","Independent finite exact arithmetic audit; all-size tensor/selector/router/analytic interfaces remain assumptions."}};std::ofstream(argv[2])<<out.dump(2)<<"\n";std::cout<<out["status"]<<" kappa="<<k.str()<<"\n";return 0;}catch(std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}

